(()=>{'use strict';if(window.__qpuDbList)return;window.__qpuDbList=true;let busy=false,last=0,all=[],pageNo=1;const pageSize=10;
const rows=x=>Array.isArray(x)?x:Array.isArray(x?.data)?x.data:Array.isArray(x?.rows)?x.rows:[];
const valid=v=>/^20\d{2}-\d{2}-\d{2}$/.test(String(v||''));
const clean=v=>String(v??'').trim();
const unwrap=r=>{let p=r?.payload||r;if(typeof p==='string'){try{p=JSON.parse(p)}catch{return {}}}return p?.data&&typeof p.data==='object'&&!Array.isArray(p.data)?p.data:p||{}};
const pick=(r,...keys)=>keys.map(k=>r?.[k]).find(v=>v!=null&&clean(v)!=='');
const date=v=>{const m=clean(v).match(/(20\d{2})[-./년\s]+(\d{1,2})[-./월\s]+(\d{1,2})/);if(!m)return '';const d=new Date(Date.UTC(+m[1],+m[2]-1,+m[3]));return d.getUTCFullYear()===+m[1]&&d.getUTCMonth()===+m[2]-1&&d.getUTCDate()===+m[3]?d.toISOString().slice(0,10):''};
const norm=v=>clean(v).toLowerCase().replace(/\s+/g,'').replace(/\s*\[kg\]/gi,'');
const supplier=r=>norm(pick(r,'supplier','vendor','supplierName','company','companyName','공급업체','거래처'));
const item=r=>norm(pick(r,'item','material','materialName','itemName','productName','품목명','원자재명'));
const lot=r=>norm(pick(r,'materialLot','lot','lotNo','LOT','원료 LOT'));
const receipt=p=>date(pick(p,'receiptDate','receipt_date','receivedDate','received_date','incomingDate','incoming_date','receiveDate','입고일자','입고일','requestedDueDate','requested_due_date'));
const inspectionDate=p=>date(pick(p,'receiptDate','receipt_date','receiveDate','receivedDate','incomingDate','inspectionDate','inspection_date','testDate','date','검사일자','검사일','입고일자','입고일'));
const minus7=d=>{const x=new Date(d+'T12:00:00Z');x.setUTCDate(x.getUTCDate()-7);return x.toISOString().slice(0,10)};
function displayRows(data,iqc){const nums={};return data.map(p=>{let d=receipt(p);if(!d){const matched=iqc.filter(r=>supplier(r)&&item(r)&&supplier(r)===supplier(p)&&item(r)===item(p)&&(!lot(p)||lot(r)===lot(p)));const unique=[...new Set(matched.map(inspectionDate).filter(Boolean))];if(unique.length===1)d=unique[0]}if(!d){const m=clean(p.purchaseNo||p.no||'').match(/^(20\d{2}-\d{2}-\d{2})-\d+$/);if(m)d=date(m[1])}if(!d)return p;const orderDate=minus7(d),key=orderDate.replace(/-/g,'');nums[key]=(nums[key]||0)+1;return {...p,displayPurchaseNo:'PO-'+key+'-'+String(nums[key]).padStart(3,'0'),orderDate,requestedDueDate:d}})}
function render(){const root=document.querySelector('#purchase'),body=root?.querySelector('.module-shell>.module-body tbody');if(!body)return;const pages=Math.max(1,Math.ceil(all.length/pageSize));pageNo=Math.min(pageNo,pages);body.replaceChildren();const head=body.closest('table')?.querySelector('thead tr');if(head?.children[5])head.children[5].textContent='수량(kg)';if(head?.lastElementChild)head.lastElementChild.textContent='비고';all.slice((pageNo-1)*pageSize,pageNo*pageSize).forEach((p,i)=>{const tr=document.createElement('tr');tr.dataset.orderNumber=String(p.displayPurchaseNo||p.purchaseNo||p.no||'');[1+(pageNo-1)*pageSize+i,p.orderDate||'',p.supplier||'',String(p.item||p.material||'').replace(/\s*(?:\[(?:kg)\]|\((?:kg)\))\s*/gi,' ').trim(),p.qty??'',p.requestedDueDate||p.due||'',p.status||'',''].forEach(v=>{const td=document.createElement('td');td.textContent=String(v);tr.append(td)});body.append(tr)});const detail=root.querySelector('.qpu-detail');if(detail){const dh=detail.querySelector('thead tr');if(dh?.lastElementChild)dh.lastElementChild.textContent='비고';detail.querySelectorAll('tbody tr').forEach(tr=>{if(tr.cells?.[1])tr.cells[1].textContent=tr.cells[1].textContent.replace(/\s*(?:\[kg\]|\(kg\))\s*/gi,' ').trim();if(tr.cells?.length===11)tr.cells[10].textContent=''})}let foot=root.querySelector('.qpu-pager');if(!foot){foot=document.createElement('div');foot.className='qpu-pager';body.closest('.module-body').after(foot)}foot.replaceChildren();if(!all.length)return;const count=document.createElement('span');count.textContent='총 '+all.length+'건 · '+pageNo+'/'+pages+' 페이지';foot.append(count);for(let n=1;n<=pages;n++){const b=document.createElement('button');b.type='button';b.textContent=n;b.className=n===pageNo?'active':'';b.onclick=()=>{pageNo=n;render()};foot.append(b)}}
async function load(force=false){const page=document.querySelector('#purchase'),body=page?.querySelector('.module-shell>.module-body tbody');if(!body||busy||(!force&&Date.now()-last<12000))return;busy=true;last=Date.now();let info=page.querySelector('.qpu-db-message');if(!info){info=document.createElement('small');info.className='qpu-db-message';info.style.cssText='display:block;padding:6px 14px;color:#526a83';body.closest('.module-body').before(info)}try{const res=await fetch('/api/purchase-orders',{credentials:'include',cache:'no-store'});const x=await res.json();if(!res.ok||x?.success===false)throw Error(x?.message||'서버 응답 '+res.status);const data=rows(x);let iqc=[];try{const ir=await fetch('/api/iqc',{credentials:'include',cache:'no-store'});if(ir.ok){const ij=await ir.json();iqc=rows(ij).map(unwrap)}}catch(err){console.warn('[QMES] IQC lookup unavailable',err)}all=displayRows(data,iqc);pageNo=1;render();info.textContent=data.length?'총 '+data.length+'건':'등록된 구매발주 내역이 없습니다.'}catch(e){info.textContent='구매발주 DB 조회 불가: '+e.message}finally{busy=false}}
document.addEventListener('click',e=>{if(e.target.closest?.('#qpu-import-dialog .qpi-save'))setTimeout(()=>load(true),1500);if(e.target.closest?.('#purchase .qpu-search,#purchase .qpu-clear'))setTimeout(()=>load(true),300)},true);
const css=document.createElement('style');css.textContent='#purchase .qpu-pager{display:flex;align-items:center;justify-content:center;gap:6px;padding:12px;border:1px solid #d0dcea;border-top:0;background:#fff}#purchase .qpu-pager span{margin-right:12px;font-size:12px;color:#526a83}#purchase .qpu-pager button{border:1px solid #d1dce8;background:#fff;border-radius:5px;min-width:30px;height:28px;cursor:pointer}#purchase .qpu-pager button.active{background:#2563eb;color:#fff;border-color:#2563eb}';document.head.append(css);function applyFilters(){const root=document.querySelector('#purchase');if(!root)return;const q=(root.querySelector('.search-input')?.value||'').trim().toLowerCase(),supplier=(root.querySelector('.qpu-supplier')?.value||'').trim(),status=root.querySelector('.qpu-status')?.value||'',inputs=root.querySelectorAll('.module-toolbar input[type=date]'),start=inputs[0]?.value||'',end=inputs[1]?.value||'';const matching=all.filter(p=>{const txt=[p.purchaseNo,p.supplier,p.item,p.material].join(' ').toLowerCase(),d=p.orderDate||'';return (!q||txt.includes(q))&&(!supplier||p.supplier===supplier)&&(!status||(p.status||'').includes(status))&&(!start||d>=start)&&(!end||d<=end)});const saved=all;all=matching;pageNo=1;render();all=saved}document.addEventListener('input',e=>{if(e.target.closest?.('#purchase .module-toolbar'))applyFilters()},true);document.addEventListener('change',e=>{if(e.target.closest?.('#purchase .module-toolbar'))applyFilters()},true);
new MutationObserver(()=>{const p=document.querySelector('#purchase');if(p?.querySelector('.module-shell>.module-body tbody')&&!p.querySelector('.qpu-db-message'))load()}).observe(document.body,{childList:true,subtree:true});load();
})();